            title: "Pourquoi y a-t-il du cobalt dans nos batteries ?",
            description: "Presque personne ne creuse pour trouver du cobalt, et pourtant il y en a dans la batterie de chaque téléphone. L'histoire d'un métal que l'industrie n'arrive pas à remplacer, et qu'elle cherche pourtant à faire disparaître.",
            subject: .sciences,
            subcategory: "Notre quotidien expliqué",
            lessons: [
                LessonPage(id: "course_266_pourquoi_y_a_t_il_du_cobalt_dans_nos_intro", title: "Introduction", content: ""),
                LessonPage(id: "course_266_pourquoi_y_a_t_il_du_cobalt_dans_nos_p1", title: "La batterie qui avait besoin de cobalt", content: ""),
                LessonPage(id: "course_266_pourquoi_y_a_t_il_du_cobalt_dans_nos_p2", title: "Une batterie qui fabrique son propre oxygène", content: ""),
                LessonPage(id: "course_266_pourquoi_y_a_t_il_du_cobalt_dans_nos_p3", title: "Pourquoi le cobalt est toujours là", content: ""),
                LessonPage(id: "course_266_pourquoi_y_a_t_il_du_cobalt_dans_nos_p4", title: "Se passer du cobalt", content: ""),
            ],
            quiz: [
        QuizQuestion(id: "course_266_pourquoi_y_a_t_il_du_cobalt_dans_nos_q1", question: "Comment la quasi-totalité du cobalt mondial est-elle extraite ?", options: ["Comme sous-produit de mines de cuivre et de nickel", "Dans des mines creusées spécialement pour lui", "Par recyclage des anciennes batteries", "Par extraction de l'eau de mer"], correctIndex: 0, explanation: "Environ 99 % du cobalt sort de terre comme sous-produit de minerais exploités pour leur cuivre ou leur nickel."),
        QuizQuestion(id: "course_266_pourquoi_y_a_t_il_du_cobalt_dans_nos_q2", type: .percentageSlider, question: "Quelle part du cobalt mondial la République démocratique du Congo fournit-elle ?", explanation: "La République démocratique du Congo fournit près des trois quarts du cobalt mondial, presque entièrement depuis des mines de cuivre.", correctValue: 75, sliderMin: 0, sliderMax: 100, tolerance: 5, unit: "%"),
        QuizQuestion(id: "course_266_pourquoi_y_a_t_il_du_cobalt_dans_nos_q3", type: .numericSlider, question: "En quelle année John Goodenough et Koichi Mizushima découvrent-ils la cathode à l'oxyde de cobalt et de lithium ?", explanation: "La découverte a lieu à Oxford en 1980 ; Sony vend la première batterie lithium-ion commerciale en 1991.", correctValue: 1980, sliderMin: 1950, sliderMax: 2010, tolerance: 2, unit: ""),
        QuizQuestion(id: "course_266_pourquoi_y_a_t_il_du_cobalt_dans_nos_q4", type: .trueFalse, question: "Vrai ou faux : la première batterie lithium-ion commerciale est vendue par Sony en 1991.", options: ["Vrai", "Faux"], correctIndex: 0, explanation: "Après plus de dix ans d'attente, Sony commercialise en 1991 la première batterie lithium-ion, avec une cathode LCO."),
        QuizQuestion(id: "course_266_pourquoi_y_a_t_il_du_cobalt_dans_nos_q5", question: "Pourquoi un feu de batterie au lithium ne peut-il pas simplement être étouffé ?", options: ["La cathode qui se décompose libère elle-même l'oxygène qui alimente le feu", "Le lithium brûle sans avoir besoin de chaleur", "Le boîtier de la batterie est fait d'un métal inflammable", "Le liquide de la cellule est plus lourd que l'air"], correctIndex: 0, explanation: "Au-dessus d'environ 130 °C ou en cas de surcharge, l'oxyde de cobalt s'effondre et libère de l'oxygène, ce qui entretient l'emballement thermique."),
        QuizQuestion(id: "course_266_pourquoi_y_a_t_il_du_cobalt_dans_nos_q6", question: "Dans l'image du mur de briques, quel rôle joue le cobalt ?", options: ["Le ciment qui empêche le mur de s'écrouler au fil des cycles", "Les briques qui entrent et sortent à chaque charge", "Le liquide qui remplit les trous du mur", "La peinture qui protège le mur de la rouille"], correctIndex: 0, explanation: "Les ions lithium sont les briques qui glissent dehors et dedans ; le cobalt tient la structure sur des centaines de cycles."),
        QuizQuestion(id: "course_266_pourquoi_y_a_t_il_du_cobalt_dans_nos_q7", question: "Par quoi la batterie LFP remplace-t-elle le cobalt ?", options: ["Du fer et du phosphore", "Du nickel et de l'aluminium", "Du manganèse et du cuivre", "De l'argent et du zinc"], correctIndex: 0, explanation: "LFP signifie lithium fer phosphate : le cobalt y est remplacé par deux éléments bon marché et abondants, le fer et le phosphore."),
        QuizQuestion(id: "course_266_pourquoi_y_a_t_il_du_cobalt_dans_nos_q8", type: .trueFalse, question: "Vrai ou faux : à poids égal, une cellule LFP stocke plus d'énergie qu'une cellule au cobalt.", options: ["Vrai", "Faux"], correctIndex: 1, explanation: "C'est l'inverse : la LFP stocke moins d'énergie pour son poids, ce qui explique qu'on la trouve dans des voitures mais pas encore dans les téléphones.")
    ]
