            quiz: [
        QuizQuestion(id: "course_267_qui_a_tue_le_premier_cable_q1", type: .numericSlider, question: "En quelle année le premier message télégraphique traverse-t-il l'Atlantique ?", explanation: "Le 16 août 1858, la reine Victoria envoie ses félicitations au président Buchanan par le câble reliant l'Irlande à Terre-Neuve.", correctValue: 1858, sliderMin: 1830, sliderMax: 1900, tolerance: 2, unit: ""),
        QuizQuestion(id: "course_267_qui_a_tue_le_premier_cable_q2", question: "Quel effet William Thomson prédit-il dans un long câble sous-marin ?", options: ["La retardation : les signaux ralentissent et s'étalent", "La surchauffe : le cuivre fond sous la tension", "L'écho : chaque signal revient à l'envoyeur", "La corrosion : l'eau de mer ronge le cuivre en quelques jours"], correctIndex: 0, explanation: "Thomson prédit que les signaux ramperont dans un long câble immergé, ce que Whitehouse conteste après des essais sur des lignes enterrées."),
        QuizQuestion(id: "course_267_qui_a_tue_le_premier_cable_q3", type: .trueFalse, question: "Vrai ou faux : les essais de Whitehouse sur des lignes télégraphiques souterraines prouvaient que le câble sous-marin fonctionnerait.", options: ["Vrai", "Faux"], correctIndex: 1, explanation: "Thomson répond qu'un câble enterré et un câble immergé ne se comportent pas de la même façon ; les essais de Whitehouse ne prouvaient rien."),
        QuizQuestion(id: "course_267_qui_a_tue_le_premier_cable_q4", question: "Pourquoi Thomson réclame-t-il une âme de cuivre plus épaisse ?", options: ["La résistance de cuivres censés identiques varie du simple au double", "Un câble fin flotte au lieu de couler", "Le cuivre fin rouille plus vite dans l'eau de mer", "Les baleines pourraient sectionner un câble trop fin"], correctIndex: 0, explanation: "Thomson mesure des résistances qui varient d'un facteur deux : une âme fine n'est pas seulement lente, elle est imprévisible."),
        QuizQuestion(id: "course_267_qui_a_tue_le_premier_cable_q5", type: .numericSlider, question: "Jusqu'à quelle tension Whitehouse envoie-t-il du courant dans le câble pour forcer une réponse ?", explanation: "Whitehouse envoie jusqu'à 2 000 volts dans un câble dont l'isolant est déjà défectueux.", correctValue: 2000, sliderMin: 100, sliderMax: 5000, tolerance: 250, unit: "volts"),
        QuizQuestion(id: "course_267_qui_a_tue_le_premier_cable_q6", question: "Comment Whitehouse fait-il croire que son instrument a reçu le message de la reine ?", options: ["Il le lit sur le galvanomètre de Thomson puis le retape sur son télégraphe imprimeur", "Il l'invente à partir des journaux de Londres", "Il le fait envoyer une seconde fois depuis Terre-Neuve", "Il recopie la bande d'un message précédent"], correctIndex: 0, explanation: "Whitehouse rebranche le galvanomètre à miroir de Thomson pour lire le message, puis le retape pour que la bande semble venir de son propre appareil."),
        QuizQuestion(id: "course_267_qui_a_tue_le_premier_cable_q7", question: "Que révèlent les tests menés dans l'eau de mer sur des chutes du câble ?", options: ["Un câble sain supporte des milliers de volts, un câble percé d'un trou d'épingle brûle", "Tous les échantillons brûlent au-delà de 500 volts", "L'eau de mer isole le câble mieux que la gutta-percha", "Le câble ne conduit plus rien après une semaine d'immersion"], correctIndex: 0, explanation: "La tension seule est supportable ; la tension à travers un défaut de fabrication ne l'est pas, et c'est exactement ce que le câble avait."),
        QuizQuestion(id: "course_267_qui_a_tue_le_premier_cable_q8", type: .chronological, question: "Remets ces étapes de l'aventure du câble transatlantique dans l'ordre.", explanation: "Le câble touche terre le 5 août 1858, le message de la reine passe le 16 août, la ligne meurt en septembre, le Great Eastern échoue en 1865 puis réussit en 1866.", items: ["Le câble atteint Valentia et Thomson passe la main à Whitehouse", "La reine Victoria félicite le président Buchanan", "La ligne meurt pour de bon et Whitehouse est renvoyé", "Le Great Eastern perd un nouveau câble en plein océan", "Le Great Eastern réussit la liaison"])
    ]
